// The browser's side of AI work: the unpublish page the email links to, the AI draft page, and
// flags in the editor. Driven through loaders and actions with a real request context.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { addFinding, saveAiDraft } from "~/lib/ai.server";
import { readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { action as aiDraftAction, loader as aiDraftLoader } from "~/routes/ai-draft";
import { action as editorAction, loader as editorLoader } from "~/routes/editor";
import { action as unpublishAction, loader as unpublishLoader } from "~/routes/unpublish";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  site = fakeSite();
  // The routes call the site through the global fetch, as the Worker does.
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function settle<T>(p: Promise<T>): Promise<T | Response> {
  try {
    return await p;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function published() {
  const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nWords.\n", expectedVersion: null, changeId: "s" });
  await site.adapter.content.publish("post-one", { expectedVersion: saved.version, changeId: "p" });
}

async function as(email: string) {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, "read") };
}

describe("the unpublish page", () => {
  it("opens without changing anything, and one button returns the post to draft", async () => {
    await published();
    const params = { project: SLUG, item: "post-one" };
    const page = (await unpublishLoader({ request: new Request("https://carrel.test/"), params, context: await context("owner@test.invalid") } as never)) as Awaited<
      ReturnType<typeof unpublishLoader>
    >;
    expect(page.item).toMatchObject({ title: "Post one", status: "published" });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("published");

    const done = await unpublishAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("owner@test.invalid") } as never);
    expect(done).toMatchObject({ ok: true, message: "Returned to draft. It is off the site." });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
  });

  it("PLANT: an Editor cannot open it or use it", async () => {
    await published();
    const params = { project: SLUG, item: "post-one" };
    expect(((await settle(unpublishLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(403);
    expect(
      ((await settle(unpublishAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("editor@test.invalid") } as never))) as Response).status,
    ).toBe(403);
    expect((await site.adapter.content.get("post-one"))?.status).toBe("published");
  });
});

describe("AI drafts in the browser", () => {
  it("shows an AI draft to the person whose session saved it, and Use as my draft replaces only their working copy", async () => {
    await published();
    const { viewer, project } = await as("owner@test.invalid");
    const saved = await saveAiDraft(env, project, { viewer, client: "Claude 1.0" }, "post-one", { source: "AI text.", note: "A note." }, site.fetch);
    const params = { project: SLUG, item: "post-one", id: String(saved.id) };
    const page = (await aiDraftLoader({ request: new Request("https://carrel.test/"), params, context: await context("owner@test.invalid") } as never)) as Awaited<ReturnType<typeof aiDraftLoader>>;
    expect(page.draft).toMatchObject({ client: "Claude 1.0", note: "A note.", source: "AI text." });

    const used = (await aiDraftAction({ request: new Request("https://carrel.test/", { method: "POST" }), params, context: await context("owner@test.invalid") } as never)) as Response;
    expect(used.headers.get("Location")).toBe(`/p/${SLUG}/e/post-one`);
    expect((await readDraft(testEnv.DB, project, viewer, "post-one"))?.source).toBe("AI text.");
    expect((await site.adapter.content.get("post-one"))?.source).toBe("---\ntitle: Post one\n---\nWords.\n");
  });

  it("PLANT: another person cannot see someone's AI draft", async () => {
    const { viewer, project } = await as("owner@test.invalid");
    const saved = await saveAiDraft(env, project, { viewer, client: "Claude" }, "post-one", { source: "Private." }, site.fetch);
    const params = { project: SLUG, item: "post-one", id: String(saved.id) };
    expect(((await settle(aiDraftLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
  });
});

describe("flags in the editor", () => {
  it("lists flags, and only the Owner dismisses one", async () => {
    await published();
    const reviewer = await viewerFor("owner@test.invalid");
    const { project } = await as("owner@test.invalid");
    const flag = await addFinding(testEnv.DB, project, { viewer: { ...reviewer, isReviewer: true }, client: "Grok Build" }, "post-one", { message: "Check this." });
    const params = { project: SLUG, item: "post-one" };
    const data = (await editorLoader({ request: new Request("https://carrel.test/"), params, context: await context("editor@test.invalid") } as never)) as Awaited<ReturnType<typeof editorLoader>>;
    expect(data.flags).toMatchObject([{ status: "open", message: "Check this. (from Grok Build)" }]);

    const dismiss = (email: string) => {
      const body = new FormData();
      body.set("intent", "dismiss-flag");
      body.set("flag", String(flag.id));
      return context(email).then((c) => settle(editorAction({ request: new Request("https://carrel.test/", { method: "POST", body }), params, context: c } as never)));
    };
    expect(((await dismiss("editor@test.invalid")) as Response).status).toBe(403);
    expect(await dismiss("owner@test.invalid")).toEqual({ intent: "dismiss-flag", dismissed: flag.id });
  });
});

test/mentions.test.ts.source:
// The webmention queue (site-api v0.5.0 mentions group): the Owner's alone to read and to decide, each
// mention its own write with its own authorship row, one failing never stopping the rest, and every
// refusal (a role, a stale version, a missing mention, a site with no mentions) leaving the site and the
// record as they were. Planted refusals assert the site was never asked.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { memoryAdapter } from "@dustinedwards/site-api/testing";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { decideMentions, listMentions, MAX_MENTION_BATCH, mentionsOffered, parseTargets, sweepMentions } from "~/lib/mentions.server";
import { requireSiteProject } from "~/lib/projects.server";
import { action as mentionsApi } from "~/routes/mentions.api";
import { loader as mentionsLoader } from "~/routes/mentions";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
type Site = ReturnType<typeof fakeSite<ReturnType<typeof memoryAdapter>>>;
let site: Site;
let env: Env;
let ids: { pending: string; second: string; approved: string; failed: string; unverified: string; oldFailed: string; oldRejected: string };

const DAY = 24 * 60 * 60 * 1000;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
  start(fakeSite());
});

function start(next: Site) {
  site = next;
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
  const ago = (days: number) => new Date(Date.now() - days * DAY);
  const send = (fields: Parameters<Site["adapter"]["receiveMention"]>[0]) => site.adapter.receiveMention(fields);
  ids = {
    pending: send({ sourceUrl: "https://a.example/one", targetId: "first-post", authorName: "Ada", excerpt: "One.", receivedAt: ago(1) }),
    second: send({ sourceUrl: "https://b.example/two", targetId: "first-post", authorName: "Bo", excerpt: "Two.", receivedAt: ago(2) }),
    approved: send({ sourceUrl: "https://c.example/three", targetId: "second-post", status: "approved", receivedAt: ago(3) }),
    failed: send({ sourceUrl: "https://d.example/four", targetId: "first-post", status: "failed", receivedAt: ago(4) }),
    unverified: send({ sourceUrl: "https://e.example/five", targetId: "first-post", status: "unverified", receivedAt: ago(0) }),
    oldFailed: send({ sourceUrl: "https://f.example/six", targetId: "first-post", status: "failed", receivedAt: ago(60) }),
    oldRejected: send({ sourceUrl: "https://g.example/seven", targetId: "second-post", status: "rejected", receivedAt: ago(200) }),
  };
}

async function as(email: string, action: "read_mentions" | "decide_mention" | "read" = "read_mentions") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, action) };
}

/** The version the page would have shown for a mention. */
const versionOf = (id: string) => site.adapter.mentionStore.get(id)!.version;
const target = (id: string) => ({ id, version: versionOf(id), status: site.adapter.mentionStore.get(id)!.status });
const decisions = async () =>
  (
    await testEnv.DB.prepare(
      "SELECT mention_id AS mentionId, action, status_before AS before, status_after AS after, change_id AS changeId, person_id AS who, client FROM mention_decisions ORDER BY id",
    ).all<{ mentionId: string | null; action: string; before: string | null; after: string | null; changeId: string; who: number; client: string | null }>()
  ).results;
const writes = () => site.requests.filter((r) => !r.startsWith("GET"));

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  return 200;
}

describe("roles: the queue is the Owner's alone (carrel/design.md: the inbox belongs to Dustin alone)", () => {
  it("PLANT: refuses an Editor and a Reader who open the queue, and the site is never asked", async () => {
    for (const email of ["editor@test.invalid", "reader@test.invalid"]) {
      expect(await refusal(as(email))).toBe(403);
    }
    expect(site.requests).toEqual([]);
  });

  it("PLANT: refuses an Editor and a Reader who decide, delete or sweep, and nothing on the site or in the record moves", async () => {
    const before = structuredClone([...site.adapter.mentionStore.values()]);
    for (const email of ["editor@test.invalid", "reader@test.invalid"]) {
      const viewer = await viewerFor(email);
      const project = await requireSiteProject(testEnv.DB, viewer, SLUG, "read");
      for (const op of ["approve", "reject", "delete"] as const) {
        expect(await refusal(decideMentions(env, project, { viewer }, op, [target(ids.pending)], site.fetch)), `${email} ${op}`).toBe(403);
      }
      expect(await refusal(sweepMentions(env, project, { viewer }, site.fetch)), `${email} sweep`).toBe(403);
      expect(await refusal(listMentions(env, project, {}, site.fetch)), `${email} list`).toBe(403);
      expect(await refusal(mentionsOffered(env, project, site.fetch)), `${email} offered`).toBe(403);
    }
    expect(site.requests).toEqual([]);
    expect([...site.adapter.mentionStore.values()]).toEqual(before);
    expect(await decisions()).toEqual([]);
  });

  it("PLANT: the screen's loader and the write endpoint refuse an Editor before the site is asked", async () => {
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor("editor@test.invalid"));
    context.set(nonceContext, "n");
    expect(await refusal(Promise.resolve(mentionsLoader({ request: new Request(`https://carrel.test/p/${SLUG}/mentions`), params: { project: SLUG }, context } as never)))).toBe(403);
    const body = new FormData();
    body.set("op", "delete");
    body.set("items", JSON.stringify([target(ids.pending)]));
    const response = (await mentionsApi({ request: new Request(`https://carrel.test/p/${SLUG}/mentions/api`, { method: "POST", body }), params: { project: SLUG }, context } as never)) as Response;
    expect(response.status).toBe(403);
    expect(await response.json()).toEqual({ error: "Deciding mentions is the Owner's step." });
    expect(site.requests).toEqual([]);
    expect(site.adapter.mentionStore.has(ids.pending)).toBe(true);
  });

  it("answers 404, not 403, for a person with no role on the project", async () => {
    await addPerson("outsider@test.invalid");
    expect(await refusal(as("outsider@test.invalid"))).toBe(404);
  });
});

describe("reading the queue", () => {
  it("opens on Pending, with the counts of the whole queue and what a sweep would remove", async () => {
    const { project } = await as("owner@test.invalid");
    const { filter, list } = await listMentions(env, project, {}, site.fetch);
    expect(filter).toBe("pending");
    expect(list.items.map((m) => m.id).sort()).toEqual([ids.pending, ids.second].sort());
    expect(list.counts).toEqual({ unverified: 1, pending: 2, approved: 1, rejected: 1, failed: 2 });
    expect(list.expiring).toEqual({ failed: 1, rejected: 1 });
  });

  it("opens on All when nothing is pending, and filters when asked", async () => {
    const { project } = await as("owner@test.invalid");
    await decideMentions(env, project, { viewer: (await as("owner@test.invalid")).viewer }, "reject", [target(ids.pending), target(ids.second)], site.fetch);
    const opened = await listMentions(env, project, {}, site.fetch);
    expect(opened.filter).toBe("all");
    expect(opened.list.items).toHaveLength(7);
    const failed = await listMentions(env, project, { filter: "failed" }, site.fetch);
    expect(failed.list.items.map((m) => m.status)).toEqual(["failed", "failed"]);
  });

  it("says why when the site does not receive mentions through Carrel", async () => {
    start(fakeSite(memoryAdapter({ mentions: false })));
    const { project } = await as("owner@test.invalid");
    expect(await mentionsOffered(env, project, site.fetch)).toEqual({ offered: false, reason: "This site does not receive webmentions through Carrel yet." });
  });

  it("says why when the site has no key", async () => {
    const { project } = await as("owner@test.invalid");
    const answer = await mentionsOffered({ ...testEnv }, project, site.fetch);
    expect(answer).toMatchObject({ offered: false });
  });
});

describe("deciding", () => {
  it("approves at the version the person saw, purges through the site, and writes one authorship row with the site's change id", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const decide = vi.spyOn(site.adapter.mentions!, "decide");
    const results = await decideMentions(env, project, { viewer }, "approve", [target(ids.pending)], site.fetch);
    expect(results).toEqual([{ id: ids.pending, ok: true, message: "Approved." }]);
    expect(site.adapter.mentionStore.get(ids.pending)!.status).toBe("approved");
    expect(site.adapter.purged).toEqual(["first-post"]);
    const log = await decisions();
    expect(log).toEqual([{ mentionId: ids.pending, action: "approve", before: "pending", after: "approved", changeId: decide.mock.calls[0]![1].changeId, who: viewer.id, client: null }]);
  });

  it("credits the AI client in the record when one decides", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    await decideMentions(env, project, { viewer, client: "Claude" }, "reject", [target(ids.pending)], site.fetch);
    expect((await decisions())[0]).toMatchObject({ action: "reject", after: "rejected", client: "Claude" });
  });

  it("deletes, with no status after, and records it", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const results = await decideMentions(env, project, { viewer }, "delete", [target(ids.failed)], site.fetch);
    expect(results).toEqual([{ id: ids.failed, ok: true, message: "Deleted." }]);
    expect(site.adapter.mentionStore.has(ids.failed)).toBe(false);
    expect(await decisions()).toMatchObject([{ mentionId: ids.failed, action: "delete", before: "failed", after: null }]);
  });

  it("PLANT: refuses a stale version for that mention alone, writes no row for it, and decides the rest", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const seen = [target(ids.pending), target(ids.second)];
    // Another door decides the first one after the page loaded.
    await decideMentions(env, project, { viewer }, "reject", [target(ids.pending)], site.fetch);
    const results = await decideMentions(env, project, { viewer }, "approve", seen, site.fetch);
    expect(results[0]).toMatchObject({ id: ids.pending, ok: false });
    expect(results[0]!.message).toMatch(/changed on the site since the page loaded/);
    expect(results[1]).toMatchObject({ id: ids.second, ok: true });
    expect(site.adapter.mentionStore.get(ids.pending)!.status).toBe("rejected");
    expect(site.adapter.mentionStore.get(ids.second)!.status).toBe("approved");
    expect((await decisions()).map((r) => [r.mentionId, r.action])).toEqual([[ids.pending, "reject"], [ids.second, "approve"]]);
  });

  it("PLANT: one missing, one the site refuses and one fine: each has its own outcome and the fine one lands", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const gone = target(ids.second);
    site.adapter.mentionStore.delete(ids.second);
    const results = await decideMentions(env, project, { viewer }, "approve", [gone, target(ids.unverified), target(ids.pending)], site.fetch);
    expect(results.map((r) => [r.id, r.ok])).toEqual([[ids.second, false], [ids.unverified, false], [ids.pending, true]]);
    expect(results[0]!.message).toMatch(/no longer has this mention/);
    expect(results[1]!.message).toMatch(/cannot be decided/);
    expect(site.adapter.mentionStore.get(ids.unverified)!.status).toBe("unverified");
    expect(await decisions()).toHaveLength(1);
  });

  it("reports a site error for one mention without stopping the next, and writes no row for it", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const real = site.adapter.mentions!.decide;
    let calls = 0;
    site.adapter.mentions!.decide = async (id, input) => {
      if (++calls === 1) throw new Error("database is locked");
      return real(id, input);
    };
    const quiet = vi.spyOn(console, "error").mockImplementation(() => {});
    const results = await decideMentions(env, project, { viewer }, "approve", [target(ids.pending), target(ids.second)], site.fetch);
    quiet.mockRestore();
    expect(results[0]).toMatchObject({ ok: false, message: "The site did not accept this change. The mention was left as it was." });
    expect(results[1]).toMatchObject({ ok: true });
    expect(await decisions()).toHaveLength(1);
  });

  it("says when the site could not clear its cache, since the decision still stands", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const real = site.adapter.mentions!.decide;
    site.adapter.mentions!.decide = async (id, input) => ({ ...(await real(id, input)), purged: false });
    const [result] = await decideMentions(env, project, { viewer }, "approve", [target(ids.pending)], site.fetch);
    expect(result).toMatchObject({ ok: true });
    expect(result!.message).toMatch(/could not clear its cache/);
    expect(await decisions()).toHaveLength(1);
  });

  it("PLANT: answers a site with no mentions in plain words, writes nothing and records nothing", async () => {
    start(fakeSite(memoryAdapter({ mentions: false })));
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const results = await decideMentions(env, project, { viewer }, "approve", [{ id: "1", version: "m1", status: "pending" }], site.fetch);
    expect(results).toEqual([{ id: "1", ok: false, message: "The site does not moderate mentions through Carrel yet." }]);
    expect(await decisions()).toEqual([]);
  });

  it("says the decision happened when only the record failed", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    // A person the database does not hold cannot be recorded (the person_id foreign key), after the site has written.
    const quiet = vi.spyOn(console, "error").mockImplementation(() => {});
    const [result] = await decideMentions(env, project, { viewer: { ...viewer, id: 99_999 } }, "reject", [target(ids.pending)], site.fetch);
    quiet.mockRestore();
    expect(result!.ok).toBe(true);
    expect(result!.message).toMatch(/could not save the record/);
    expect(site.adapter.mentionStore.get(ids.pending)!.status).toBe("rejected");
    expect(await decisions()).toEqual([]);
  });

  it("refuses an empty choice, and too many, before the site is asked", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    expect(await refusal(decideMentions(env, project, { viewer }, "approve", [], site.fetch))).toBe(400);
    const many = Array.from({ length: MAX_MENTION_BATCH + 1 }, (_, i) => ({ id: String(i + 1), version: "m1", status: "pending" }));
    expect(await refusal(decideMentions(env, project, { viewer }, "approve", many, site.fetch))).toBe(400);
    expect(site.requests).toEqual([]);
  });

  it("does not send an id or a version a site could not hold", () => {
    const parsed = parseTargets([
      { id: "12", version: "m1", status: "pending" },
      { id: "12", version: "m1", status: "pending" },
      { id: "../x", version: "m1", status: "pending" },
      { id: "13", version: "", status: "pending" },
      { id: "14", version: "m1", status: "bogus" },
      "nonsense",
    ]);
    expect(parsed.targets).toEqual([{ id: "12", version: "m1", status: "pending" }]);
    expect(parsed.invalid).toEqual(["../x", "13", "14", "(no id)"]);
  });
});

describe("sweeping", () => {
  it("removes what the site says is expired, keeps the rest, and records one row with no mention id", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const result = await sweepMentions(env, project, { viewer }, site.fetch);
    expect(result).toMatchObject({ ok: true, removed: { failed: 1, rejected: 1 }, recorded: true });
    expect(site.adapter.mentionStore.has(ids.oldFailed)).toBe(false);
    expect(site.adapter.mentionStore.has(ids.oldRejected)).toBe(false);
    expect(site.adapter.mentionStore.has(ids.failed)).toBe(true);
    expect(site.adapter.mentionStore.has(ids.pending)).toBe(true);
    expect(await decisions()).toMatchObject([{ mentionId: null, action: "sweep", before: null, after: null, who: viewer.id }]);
  });

  it("PLANT: a site with no mentions answers in plain words, and nothing is recorded", async () => {
    start(fakeSite(memoryAdapter({ mentions: false })));
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    expect(await sweepMentions(env, project, { viewer }, site.fetch)).toEqual({ ok: false, message: "The site does not moderate mentions through Carrel yet." });
    expect(await decisions()).toEqual([]);
  });

  it("goes through the endpoint for the Owner as JSON", async () => {
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor("owner@test.invalid"));
    context.set(nonceContext, "n");
    const body = new FormData();
    body.set("op", "sweep");
    const response = (await mentionsApi({ request: new Request(`https://carrel.test/p/${SLUG}/mentions/api`, { method: "POST", body }), params: { project: SLUG }, context } as never)) as Response;
    expect(response.status).toBe(200);
    expect(((await response.json()) as { sweep: unknown }).sweep).toMatchObject({ ok: true, removed: { failed: 1, rejected: 1 } });
    expect(writes()).toEqual(["POST /api/carrel/v1/mentions/sweep"]);
  });
});

describe("the migration", () => {
  it("PLANT: refuses a record that names no mention for anything but a sweep, and a status after a delete", async () => {
    const { viewer, project } = await as("owner@test.invalid", "decide_mention");
    const insert = (mention: string | null, action: string, after: string | null) =>
      testEnv.DB.prepare("INSERT INTO mention_decisions (project_id, mention_id, person_id, action, status_after, change_id) VALUES (?, ?, ?, ?, ?, ?)")
        .bind(project.id, mention, viewer.id, action, after, crypto.randomUUID())
        .run();
    await expect(insert(null, "approve", "approved")).rejects.toThrow();
    await expect(insert("1", "approve", null)).rejects.toThrow();
    await expect(insert("1", "approve", "spam")).rejects.toThrow();
    await expect(insert("1", "launch", "approved")).rejects.toThrow();
    await insert(null, "sweep", null);
    await insert("1", "delete", null);
    expect((await decisions()).map((r) => r.action)).toEqual(["sweep", "delete"]);
  });
});

test/legal.test.ts.source:
// Legal pages: shared sections written into each site's page, the fields they take, the date stamped
// on an Owner publish of a changed text, and the page the site's data license names that Carrel never
// takes down or moves. The write tests run Carrel's real code against site-api's reference site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it } from "vitest";

import { writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { readFields, splitSource } from "~/lib/frontmatter";
import { expandShared, legalTypeOf, prepareLegalWrite, sectionsUsed, type SharedSection } from "~/lib/legal";
import { deleteSection, listSections, saveSection } from "~/lib/legal.server";
import { requireSiteProject } from "~/lib/projects.server";
import { siteEntry } from "~/lib/sites.server";
import { action as legalAction, loader as legalLoader } from "~/routes/legal";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

const SECTIONS: SharedSection[] = [
  { key: "hosting", title: "Hosting", body: "{{site_name}} runs on Cloudflare. Questions go to {{contact}}." },
  { key: "analytics", title: "Analytics", body: "Cloudflare Web Analytics counts visits without tracking cookies." },
];

const FRONT = ["---", "path: /privacy", 'title: "Privacy"', "legal_type: privacy", 'site_name: "dustinedwards.info"', 'contact: "hello@example.test"', "---", ""].join("\n");

describe("expandShared", () => {
  it("writes each section between its markers with the page's fields filled in", () => {
    const out = expandShared("Intro.\n\n<!-- shared:hosting -->\n", SECTIONS, { site_name: "dustinedwards.info", contact: "hello@example.test" });
    expect(out.text).toBe(
      "Intro.\n\n<!-- shared:hosting -->\ndustinedwards.info runs on Cloudflare. Questions go to hello@example.test.\n<!-- /shared:hosting -->\n",
    );
    expect(out.unknownSections).toEqual([]);
    expect(out.missingFields).toEqual([]);
  });

  it("gives the same text when run again, so a page is expanded on every write", () => {
    const values = { site_name: "A", contact: "b@example.test" };
    const once = expandShared("<!-- shared:hosting -->\n\n<!-- shared:analytics -->\n", SECTIONS, values).text;
    expect(expandShared(once, SECTIONS, values).text).toBe(once);
    expect(sectionsUsed(once)).toEqual(["hosting", "analytics"]);
  });

  it("replaces text a person typed inside the markers, since the section is the source", () => {
    const out = expandShared("<!-- shared:analytics -->\nold wording\n<!-- /shared:analytics -->", SECTIONS, {});
    expect(out.text).not.toContain("old wording");
  });

  it("names an unknown section and a missing field, and leaves both as written", () => {
    const out = expandShared("<!-- shared:nope -->\n<!-- shared:hosting -->", SECTIONS, { site_name: "A" });
    expect(out.unknownSections).toEqual(["nope"]);
    expect(out.missingFields).toEqual(["contact"]);
    expect(out.text).toContain("<!-- shared:nope -->");
    expect(out.text).toContain("{{contact}}");
  });
});

describe("prepareLegalWrite", () => {
  const base = { sections: SECTIONS, today: "2026-10-06" };

  it("stamps last_updated when the Owner publishes a changed text", () => {
    const result = prepareLegalWrite({ ...base, source: `${FRONT}New.\n`, stored: `${FRONT}Old.\n`, storedPublic: true, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("2026-10-06");
  });

  it("leaves the date alone when only a field changed", () => {
    const stored = `${FRONT}Same.\n`;
    const result = prepareLegalWrite({ ...base, source: stored.replace("hello@example.test", "other@example.test"), stored, storedPublic: true, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("");
  });

  it("stamps a draft that goes public even if its text was already saved", () => {
    const stored = `${FRONT}Saved earlier.\n`;
    const result = prepareLegalWrite({ ...base, source: stored, stored, storedPublic: false, public: true });
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("2026-10-06");
  });

  it("does not stamp a draft save, and keeps a missing field's token so no work is lost", () => {
    const source = FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n";
    const result = prepareLegalWrite({ ...base, source, stored: null, storedPublic: false, public: false });
    expect(result.ok && result.source).toContain("{{contact}}");
    expect(result.ok && readFields(splitSource(result.source).front).last_updated).toBe("");
  });

  it("refuses to go public with a field missing or a section unknown, and says which", () => {
    const missing = prepareLegalWrite({ ...base, source: FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n", stored: null, storedPublic: false, public: true });
    expect(!missing.ok && missing.message).toContain("contact");
    const unknown = prepareLegalWrite({ ...base, source: `${FRONT}<!-- shared:nope -->\n`, stored: null, storedPublic: false, public: true });
    expect(!unknown.ok && unknown.message).toContain('"nope"');
  });

  it("recognises a legal page by its legal_type", () => {
    expect(legalTypeOf(FRONT)).toBe("privacy");
    expect(legalTypeOf("---\ntitle: x\n---\n")).toBeNull();
    expect(legalTypeOf("no frontmatter")).toBeNull();
  });
});

let projectId: number;
let ownerId: number;

beforeEach(async () => {
  await resetDb();
  ownerId = await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  for (const s of SECTIONS) {
    await testEnv.DB.prepare("INSERT INTO legal_sections (key, title, body, updated_by) VALUES (?, ?, ?, ?)").bind(s.key, s.title, s.body, ownerId).run();
  }
});

async function as(email: string) {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, "read") };
}

async function seed(site: ReturnType<typeof fakeSite>, id: string, source: string) {
  const { viewer, project } = await as("owner@test.invalid");
  const saved = await writeToSite(connectedEnv(), project, viewer, id, { action: "save", source, expectedVersion: null }, site.fetch);
  if (!saved.ok) throw new Error(saved.message);
  return saved.version;
}

const writes = (site: ReturnType<typeof fakeSite>) => site.requests.filter((r) => !r.startsWith("GET"));

describe("a legal page written to the site", () => {
  it("is published with its shared sections filled in and its date stamped, through the real write path", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.privacy", `${FRONT}Intro.\n\n<!-- shared:hosting -->\n`);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version }, site.fetch);
    expect(published.ok).toBe(true);
    // A publish with no text sends the stored text, so the stored text is what the draft save wrote.
    const doc = await site.adapter.content.get("page.privacy");
    expect(doc?.source).toContain("dustinedwards.info runs on Cloudflare. Questions go to hello@example.test.");
    expect(doc?.status).toBe("published");
  });

  it("stamps last_updated when the text sent with a publish changed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.privacy", `${FRONT}Intro.\n`);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version, source: `${FRONT}Changed.\n` }, site.fetch);
    expect(published.ok).toBe(true);
    expect(readFields(splitSource((await site.adapter.content.get("page.privacy"))!.source).front).last_updated).toBe(new Date().toISOString().slice(0, 10));
  });

  it("is refused at publish with a field missing, and the site hears no write after the seed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const source = FRONT.replace('contact: "hello@example.test"\n', "") + "<!-- shared:hosting -->\n";
    const version = await seed(site, "page.privacy", source);
    const before = writes(site).length;
    const published = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "publish", expectedVersion: version, source }, site.fetch);
    expect(published).toMatchObject({ ok: false, reason: "refused" });
    expect(writes(site).length).toBe(before);
  });

  it("is an ordinary item for an AI session: no special refusal, the same role rules", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("editor@test.invalid");
    const saved = await writeToSite(connectedEnv(), project, viewer, "page.privacy", { action: "save", source: `${FRONT}Draft text.\n`, expectedVersion: null }, site.fetch, { client: "claude" });
    expect(saved.ok).toBe(true);
  });
});

describe("PLANT: the page the site's data license names", () => {
  const TERMS = ["---", "path: /terms", 'title: "Terms"', "legal_type: terms", "---", "The terms.", ""].join("\n");

  it("cannot be unpublished through Carrel, and the site hears nothing", async () => {
    expect(siteEntry("dustinedwards").keepPublic).toContain("page.terms");
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const published = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "publish", expectedVersion: version }, site.fetch);
    if (!published.ok) throw new Error(published.message);
    const before = writes(site).length;
    const result = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "unpublish", expectedVersion: published.version }, site.fetch);
    expect(result).toMatchObject({ ok: false, reason: "refused" });
    expect(writes(site).length).toBe(before);
    expect((await site.adapter.content.get("page.terms"))?.status).toBe("published");
  });

  it("can have its wording changed, but not its path", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const moved = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("path: /terms", "path: /legal"), expectedVersion: version }, site.fetch);
    expect(moved).toMatchObject({ ok: false, reason: "refused" });
    expect((moved as { message: string }).message).toContain("/terms");
    const reworded = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("The terms.", "Better terms."), expectedVersion: version }, site.fetch);
    expect(reworded.ok).toBe(true);
  });

  it("is guarded by id even when its legal_type is removed", async () => {
    const site = fakeSite();
    const { viewer, project } = await as("owner@test.invalid");
    const version = await seed(site, "page.terms", TERMS);
    const moved = await writeToSite(connectedEnv(), project, viewer, "page.terms", { action: "save", source: TERMS.replace("legal_type: terms\n", "").replace("path: /terms", "path: /legal"), expectedVersion: version }, site.fetch);
    expect(moved).toMatchObject({ ok: false, reason: "refused" });
  });
});

describe("the shared sections", () => {
  it("are changed only by the Owner", async () => {
    const editor = await as("editor@test.invalid");
    await expect(saveSection(testEnv.DB, editor.project, editor.viewer, { key: "x", title: "X", body: "Text." })).rejects.toMatchObject({ status: 403 });
    await expect(deleteSection(testEnv.DB, editor.project, "hosting")).rejects.toMatchObject({ status: 403 });
    const owner = await as("owner@test.invalid");
    expect(await saveSection(testEnv.DB, owner.project, owner.viewer, { key: "x", title: "X", body: "Text." })).toEqual({ ok: true });
    expect((await listSections(testEnv.DB)).map((s) => s.key)).toEqual(["analytics", "hosting", "x"]);
  });

  it("refuse a bad name, an empty text and a wide dash", async () => {
    const owner = await as("owner@test.invalid");
    for (const input of [
      { key: "Bad Name", title: "T", body: "B" },
      { key: "ok", title: "", body: "B" },
      { key: "ok", title: "T", body: "One — two." },
    ]) {
      expect((await saveSection(testEnv.DB, owner.project, owner.viewer, input)).ok).toBe(false);
    }
  });
});

describe("the Legal tab", () => {
  async function contextFor(email: string) {
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env: connectedEnv(), ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor(email));
    context.set(nonceContext, "test-nonce");
    return context;
  }

  it("lists each legal page, says which are not set up, and flags a page behind the shared text", async () => {
    const site = fakeSite();
    const realFetch = globalThis.fetch;
    globalThis.fetch = site.fetch;
    try {
      await seed(site, "page.privacy", `${FRONT}<!-- shared:analytics -->\n`);
      // The shared text changes after the page was written to the site.
      await testEnv.DB.prepare("UPDATE legal_sections SET body = ? WHERE key = ?").bind("Newer wording.", "analytics").run();
      const data = (await legalLoader({ params: { project: SLUG }, context: await contextFor("owner@test.invalid"), request: new Request("https://carrel.test/p/de-info/legal") } as never)) as {
        pages: { type: string; setUp: boolean; behind?: boolean; shared?: string[] }[];
        canManage: boolean;
        sections: unknown[];
      };
      expect(data.pages.map((p) => [p.type, p.setUp])).toEqual([["privacy", true], ["terms", false]]);
      expect(data.pages[0]).toMatchObject({ behind: true, shared: ["analytics"] });
      expect(data.canManage).toBe(true);
      expect(data.sections).toHaveLength(2);
    } finally {
      globalThis.fetch = realFetch;
    }
  });

  it("changes a section only for the Owner, through the action", async () => {
    const body = new FormData();
    body.set("intent", "save-section");
    body.set("key", "hosting");
    body.set("title", "Hosting");
    body.set("body", "New text.");
    const request = () => new Request("https://carrel.test/p/de-info/legal", { method: "POST", body });
    const ok = await legalAction({ params: { project: SLUG }, context: await contextFor("owner@test.invalid"), request: request() } as never);
    expect(ok).toMatchObject({ saved: "hosting" });
    await expect(legalAction({ params: { project: SLUG }, context: await contextFor("editor@test.invalid"), request: request() } as never)).rejects.toMatchObject({ status: 403 });
  });
});

test/editor-ux.test.ts.source:
// The editor and AI draft screens' behaviour behind the UX pass: "Use as my draft" writes the
// person's working copy in Carrel and nothing to the site, the AI draft's rendered view is private
// to its owner, and the save line says a draft on the site is not live.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { siteState } from "~/lib/save-state";
import { action as aiDraftAction } from "~/routes/ai-draft";
import { loader as aiPreviewLoader } from "~/routes/ai-draft.preview";

import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
const THEIR_SOURCE = "---\ntitle: The AI's take\nunknown_key: kept\n---\nAn alternative opening.\n";
let site: ReturnType<typeof fakeSite>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function aiDraftFor(email: string, item: string) {
  const viewer = await viewerFor(email);
  const project = await requireSiteProject(env.DB, viewer, SLUG, "edit");
  const { id } = await saveAiDraft(env, project, { viewer, client: "Claude" }, item, { source: THEIR_SOURCE });
  return { id, viewer, project };
}

describe("Use as my draft", () => {
  it("writes the working copy in Carrel exactly as the AI wrote it, and sends nothing to the site", async () => {
    const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Site copy\n---\nOn the site.\n", expectedVersion: null, changeId: "s" });
    const { id, viewer, project } = await aiDraftFor("owner@test.invalid", "post-one");
    const before = site.requests.length;

    const result = await aiDraftAction({ params: { project: SLUG, item: "post-one", id: String(id) }, request: new Request("https://carrel.test/", { method: "POST" }), context: await context("owner@test.invalid") } as never);
    expect((result as Response).status).toBe(302);

    expect(await readDraft(env.DB, project, viewer, "post-one")).toMatchObject({ source: THEIR_SOURCE });
    expect(site.requests.slice(before).filter((r) => !r.startsWith("GET "))).toEqual([]);
    const onSite = await site.adapter.content.get("post-one");
    expect(onSite?.version).toBe(saved.version);
    expect(onSite?.source).toContain("On the site.");
  });
});

describe("the AI draft's rendered view", () => {
  it("renders the draft through the site for its owner", async () => {
    const { id } = await aiDraftFor("owner@test.invalid", "post-one");
    const response = (await aiPreviewLoader({ params: { project: SLUG, item: "post-one", id: String(id) }, context: await context("owner@test.invalid") } as never)) as Response;
    expect(response.status).toBe(200);
    expect(response.headers.get("Content-Security-Policy")).toMatch(/^sandbox; default-src 'none'/);
    expect(await response.text()).toContain("The AI's take");
  });

  it("PLANT: is never shown to another person, whose request answers 404", async () => {
    const { id } = await aiDraftFor("owner@test.invalid", "post-one");
    await expect(aiPreviewLoader({ params: { project: SLUG, item: "post-one", id: String(id) }, context: await context("editor@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });
});

describe("the save line", () => {
  it("does not read as live for a draft on the site", () => {
    expect(siteState("draft", false)).toBe("Saved as a draft on the site. Not published yet.");
    expect(siteState("draft", true)).toBe("Matches the site's draft. It is not live.");
    expect(siteState("scheduled", true)).toMatch(/scheduled/);
    expect(siteState("published", true)).toBe("Matches the live post");
  });
});

test/media.test.ts.source:
// The media library (stage 3) over site-api v0.2.0's media group. The site is site-api's own handler
// over its reference adapter, whose reference check scans post sources for /media/<id> as
// dustinedwards.info's does. Planted: each role refusal, a delete of a file a post uses (refused with
// the post named), an upload the site would refuse (never sent), and bytes the site API refuses.

import { memoryAdapter } from "@dustinedwards/site-api/testing";
import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { runHealth } from "~/lib/health.server";
import { deleteMedia, listMedia, mediaDetail, mediaLimits, uploadMedia } from "~/lib/media.server";
import { requireSiteProject } from "~/lib/projects.server";
import { figureMarkup } from "~/lib/site-markdown";
import { loader as editorLoader } from "~/routes/editor";
import { action as mediaAction, loader as mediaLoader } from "~/routes/media";
import { action as apiAction, loader as apiLoader } from "~/routes/media.api";

import { appPolicy } from "../workers/csp";
import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, SITE_ORIGIN, viewerFor } from "./site";

const SLUG = "de-info";
const PNG = Uint8Array.from(
  atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="),
  (c) => c.charCodeAt(0),
);

let site: ReturnType<typeof fakeSite<ReturnType<typeof memoryAdapter>>>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  site = fakeSite();
  env = connectedEnv();
  vi.stubGlobal("fetch", site.fetch);
});

async function project(email: string, action: Parameters<typeof requireSiteProject>[3] = "read") {
  return requireSiteProject(env.DB, await viewerFor(email), SLUG, action);
}

async function actor(email: string) {
  return { viewer: await viewerFor(email) };
}

function file(bytes: Uint8Array, name = "river.png", type = "image/png") {
  return { name, type, size: bytes.byteLength, bytes: async () => bytes.slice().buffer };
}

async function status(run: () => Promise<unknown>): Promise<number> {
  try {
    await run();
    return 200;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
}

async function contextFor(email: string, e: Env = env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env: e, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  return context;
}

/** A file on the site, uploaded as the site would take it from anyone. */
async function seedFile(name = "river.png") {
  return site.adapter.media!.upload({ bytes: PNG, contentType: "image/png", filename: name, alt: "The river", changeId: "seed" });
}

describe("the library through the site API", () => {
  it("lists, searches and reads a file with its uses, and shows it at the site's own address", async () => {
    const item = await seedFile();
    const reader = await project("reader@test.invalid");
    const list = await listMedia(env, reader, {});
    expect(list.items).toMatchObject([{ id: item.id, url: `/media/${item.id}`, src: `${SITE_ORIGIN}/media/${item.id}`, alt: "The river" }]);
    expect((await listMedia(env, reader, { q: "nothing-like-it" })).items).toEqual([]);
    expect(await mediaDetail(env, reader, item.id)).toMatchObject({ id: item.id, usedBy: [] });
    expect(await mediaDetail(env, reader, "uploads/no-such.png")).toBeNull();
    expect(await mediaLimits(env, reader)).toMatchObject({ types: expect.arrayContaining(["image/png"]) });
  });

  it("uploads as an Editor into the site's own storage", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(PNG), "The river at dusk");
    expect(outcome).toMatchObject({ ok: true, item: { filename: "river.png", alt: "The river at dusk", src: expect.stringMatching(/^https:\/\/site\.test\/media\//) } });
    expect(site.adapter.mediaStore.size).toBe(1);
  });

  it("deletes as the Owner", async () => {
    const item = await seedFile();
    expect(await deleteMedia(env, await project("owner@test.invalid"), await actor("owner@test.invalid"), item.id)).toEqual({ ok: true });
    expect(site.adapter.deleted).toEqual([item.id]);
  });
});

describe("PLANT: roles", () => {
  it("refuses a Reader's upload, and the site hears nothing", async () => {
    const reader = await project("reader@test.invalid");
    expect(await status(async () => uploadMedia(env, reader, await actor("reader@test.invalid"), file(PNG), ""))).toBe(403);
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
  });

  it("refuses an Editor's delete, and the file stays", async () => {
    const item = await seedFile();
    const editor = await project("editor@test.invalid");
    expect(await status(async () => deleteMedia(env, editor, await actor("editor@test.invalid"), item.id))).toBe(403);
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
    expect(site.requests.filter((r) => r.startsWith("DELETE"))).toEqual([]);
  });

  it("answers 404 to someone the project is not shared with", async () => {
    expect(await status(() => project("stranger@test.invalid"))).toBe(404);
  });

  it("refuses at the routes too: a Reader's upload and an Editor's delete", async () => {
    await seedFile();
    const form = new FormData();
    form.set("file", new File([PNG], "river.png", { type: "image/png" }));
    const upload = new Request(`https://carrel.test/p/${SLUG}/media/api`, { method: "POST", body: form });
    const readerContext = await contextFor("reader@test.invalid");
    expect(await status(() => apiAction({ request: upload, params: { project: SLUG }, context: readerContext } as never))).toBe(403);
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);

    const del = new FormData();
    del.set("intent", "delete");
    del.set("id", "uploads/1-river.png");
    del.set("confirm", "delete");
    const request = new Request(`https://carrel.test/p/${SLUG}/media`, { method: "POST", body: del });
    const context = await contextFor("editor@test.invalid");
    expect(await status(() => mediaAction({ request, params: { project: SLUG }, context } as never))).toBe(403);
    expect(site.adapter.mediaStore.size).toBe(1);
  });
});

describe("PLANT: deleting a file a post uses", () => {
  it("is refused by the site's reference check, with the post named, and the file stays", async () => {
    const item = await seedFile();
    await site.adapter.content.saveDraft("river-post", {
      source: `---\ntitle: The river\n---\nIntro.\n\n:::figure{src="${item.url}" alt="The river"}\n:::\n`,
      expectedVersion: null,
      changeId: "c1",
    });
    const owner = await project("owner@test.invalid");
    expect(await mediaDetail(env, owner, item.id)).toMatchObject({ usedBy: [{ id: "river-post", title: "The river", detail: "line 6" }] });

    const outcome = await deleteMedia(env, owner, await actor("owner@test.invalid"), item.id);
    expect(outcome).toMatchObject({ ok: false, usedBy: [{ type: "post", id: "river-post", title: "The river", detail: "line 6" }] });
    expect(!outcome.ok && outcome.message).toContain("The river (line 6)");
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
    expect(site.adapter.deleted).toEqual([]);
  });

  it("asks before it deletes, then shows the refusal on the page", async () => {
    const item = await seedFile();
    await site.adapter.content.saveDraft("river-post", { source: `# The river\n\n![](${item.url})\n`, expectedVersion: null, changeId: "c1" });
    const post = async (fields: Record<string, string>) => {
      const form = new FormData();
      for (const [k, v] of Object.entries(fields)) form.set(k, v);
      const request = new Request(`https://carrel.test/p/${SLUG}/media`, { method: "POST", body: form });
      return mediaAction({ request, params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never);
    };
    expect(await post({ intent: "delete", id: item.id })).toEqual({ intent: "delete", needsConfirm: true, id: item.id });
    expect(site.requests.filter((r) => r.startsWith("DELETE"))).toEqual([]);
    expect(await post({ intent: "delete", id: item.id, confirm: "delete" })).toMatchObject({
      intent: "delete",
      ok: false,
      usedBy: [{ id: "river-post", title: "The river" }],
    });
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
  });
});

describe("PLANT: an upload the site does not accept", () => {
  it("refuses a type the site did not declare before sending anything", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(new TextEncoder().encode("<script>x</script>"), "page.html", "text/html"), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("this site accepts") });
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
  });

  it("refuses a file over the site's limit before sending anything", async () => {
    site = fakeSite(memoryAdapter({ media: { maxBytes: 64, types: ["image/png"] } }));
    vi.stubGlobal("fetch", site.fetch);
    const big = new Uint8Array(65);
    big.set(PNG.subarray(0, 8));
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(big), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("accepts files up to") });
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
    expect(site.adapter.mediaStore.size).toBe(0);
  });

  it("shows the site API's refusal of bytes that are not their type, and stores nothing", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(new TextEncoder().encode("not a png at all"), "fake.png"), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("The site refused fake.png") });
    expect(site.adapter.mediaStore.size).toBe(0);
  });
});

describe("a site with no media library", () => {
  beforeEach(() => {
    site = fakeSite(memoryAdapter({ media: false }));
    vi.stubGlobal("fetch", site.fetch);
  });

  it("says so on the page, and the editor gets no image tools", async () => {
    const data = (await mediaLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media`), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)) as { unavailable: string | null };
    expect(data.unavailable).toBe("This site has no media library yet.");
    await site.adapter.content.saveDraft("post-one", { source: "# One\n", expectedVersion: null, changeId: "s" });
    const editor = (await editorLoader({ params: { project: SLUG, item: "post-one" }, context: await contextFor("owner@test.invalid") } as never)) as { media: unknown };
    expect(editor.media).toBeNull();
  });
});

describe("the editor's image tools", () => {
  it("are given to an Editor with the site's accepted types, and never to a Reader", async () => {
    await site.adapter.content.saveDraft("post-one", { source: "# One\n", expectedVersion: null, changeId: "s" });
    const load = async (email: string) =>
      (await editorLoader({ params: { project: SLUG, item: "post-one" }, context: await contextFor(email) } as never)) as { media: { endpoint: string; accept: string } | null };
    expect((await load("editor@test.invalid")).media).toEqual({ endpoint: `/p/${SLUG}/media/api`, accept: expect.stringContaining("image/png") });
    expect((await load("reader@test.invalid")).media).toBeNull();
  });

  it("uploads through the endpoint and answers the site's address and where to show it", async () => {
    const form = new FormData();
    form.set("file", new File([PNG], "river.png", { type: "image/png" }));
    const request = new Request(`https://carrel.test/p/${SLUG}/media/api`, { method: "POST", body: form });
    const response = (await apiAction({ request, params: { project: SLUG }, context: await contextFor("editor@test.invalid") } as never)) as Response;
    expect(response.status).toBe(201);
    const body = (await response.json()) as { url: string; src: string };
    expect(body.url).toMatch(/^\/media\/uploads\//);
    expect(body.src).toBe(`${SITE_ORIGIN}${body.url}`);
  });

  it("lists for the picker, and says why when the site cannot be reached", async () => {
    await seedFile();
    const list = (await apiLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media/api?q=river`), params: { project: SLUG }, context: await contextFor("reader@test.invalid") } as never)) as Response;
    expect(((await list.json()) as { items: unknown[] }).items).toHaveLength(1);
    const offline = { ...env, SITE_DUSTINEDWARDS_KEY: "" };
    const answer = (await apiLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media/api`), params: { project: SLUG }, context: await contextFor("reader@test.invalid", offline) } as never)) as Response;
    expect(await answer.json()).toMatchObject({ items: [], error: expect.stringContaining("not connected") });
  });

  it("inserts the site's own figure, with the alt text escaped", () => {
    expect(figureMarkup("dustinedwards", "/media/a.png", ' The "river" ')).toBe(':::figure{src="/media/a.png" alt="The &quot;river&quot;"}\n:::');
    expect(figureMarkup("some-other-site", "/media/a.png", "A [river]")).toBe("![A river](/media/a.png)");
  });
});

describe("the image policy", () => {
  it("loads images from the configured sites, and drops anything that is not a plain https origin", () => {
    const policy = appPolicy("n", ["https://site.test", "https://evil.test; script-src *", "http://plain.test"]);
    expect(policy).toContain("img-src 'self' data: https://site.test;");
    expect(policy).not.toContain("evil.test");
    expect(policy).not.toContain("plain.test");
  });
});

describe("health", () => {
  it("runs the media conformance against a site with media, and never stores or deletes a file", async () => {
    const existing = await seedFile();
    const box = { sent: [] as unknown[] };
    const EMAIL = { send: async (m: unknown) => (box.sent.push(m), { messageId: "m" }) } as unknown as SendEmail;
    const fetcher = (async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
      return url.includes("cloudflareaccess") ? Response.json({ keys: [{ kid: "k" }] }) : site.fetch(url, init);
    }) as unknown as Parameters<typeof runHealth>[1];
    const { results } = await runHealth({ ...env, EMAIL }, fetcher);
    expect(results.find((r) => r.name === "site-dustinedwards")).toMatchObject({ ok: true });
    expect(site.requests).toEqual(expect.arrayContaining(["GET /api/carrel/v1/media", "DELETE /api/carrel/v1/media/carrel-conformance-probe%2Fno-such-file.png", "POST /api/carrel/v1/media"]));
    expect([...site.adapter.mediaStore.keys()]).toEqual([existing.id]);
    expect(site.adapter.deleted).toEqual([]);
  });
});

test/checks.test.ts.source:
// Planted problems for the checks on save (design section 7): each check must flag its plant and stay
// quiet on the clean twin beside it. The checks are pure, so these run without Git or D1.

import { describe, expect, it } from "vitest";

import {
  checkAiHabits,
  checkContinuity,
  checkFile,
  checkRuleFile,
  checkTimeline,
  checkVoice,
  checkWorldRules,
  fingerprints,
  readHabits,
  SEED_WORDS,
  storyDate,
  type Bible,
  type BookContext,
} from "~/lib/novels/checks";
import { parseFile } from "~/lib/novels/frontmatter";
import { readMeta, type SceneHeader } from "~/lib/novels/layout";
import { profileOf } from "~/lib/novels/voice";

import { BASELINE, PLANT, TWIN } from "./fixtures/voice";

const BIBLE: Bible = {
  characters: [
    { name: "Wade Pruitt", aliases: ["Wade"], born: "1996-02-11", died: "" },
    { name: "June Harlan", aliases: ["Mrs. Harlan"], born: "1931-05-02", died: "2019-08-30" },
    { name: "Nell", aliases: [], born: "2031-01-01", died: "" },
  ],
  places: [{ name: "Harlan place", aliases: ["the farm"] }, { name: "Paluxy crossing", aliases: [] }],
  rules: [{ name: "No phones past the ridge", forbidden: ["\\bphone rang\\b", "text(?:ed)? (?:her|him|me)"] }],
};

function scene(header: Partial<Record<keyof SceneHeader, string | string[] | boolean>>, body = "Plain prose.\n"): string {
  const lines = ["---"];
  for (const [k, v] of Object.entries(header)) lines.push(`${k}: ${Array.isArray(v) ? `[${v.join(", ")}]` : String(v)}`);
  lines.push("---", "", body);
  return lines.join("\n");
}

function headerOf(path: string, source: string): SceneHeader {
  const meta = readMeta(path, parseFile(source).data, true);
  if (meta.kind !== "scene") throw new Error("not a scene");
  return meta.header;
}

const FULL = { pov: "Wade", date: "2024-04-12", location: "Harlan place", characters: ["Wade"], goal: "g", conflict: "c", outcome: "o" };

describe("PLANT: continuity", () => {
  const path = "chapters/01-arrival/01-the-gate.md";
  const run = (source: string) => checkContinuity(path, source, headerOf(path, source), BIBLE);

  it("flags a character not in the bible", () => {
    const found = run(scene({ ...FULL, characters: ["Wade", "Tobias"] }));
    expect(found.map((f) => f.message)).toEqual(["Tobias is in this scene but not in the bible (bible/characters/)."]);
    expect(found[0]!.line).toBe(5);
  });

  it("flags a dead character present, found by alias", () => {
    const found = run(scene({ ...FULL, characters: ["Wade", "Mrs. Harlan"] }));
    expect(found).toHaveLength(1);
    expect(found[0]!.message).toBe("June Harlan died 2019-08-30, before this scene (2024-04-12), and is present in it.");
  });

  it("flags a character not born yet, and a location not in the bible", () => {
    const found = run(scene({ ...FULL, characters: ["Nell"], location: "Glen Rose" }));
    expect(found.map((f) => f.check)).toEqual(["continuity", "continuity"]);
    expect(found[0]!.message).toContain("Nell is born 2031-01-01, after this scene");
    expect(found[1]!.message).toBe('The location "Glen Rose" is not in the bible (bible/places/).');
  });

  it("CLEAN TWIN: everyone known and alive, the place known by alias: nothing", () => {
    expect(run(scene({ ...FULL, characters: ["Wade", "Mrs. Harlan"], date: "2012-06-01", location: "the farm" }))).toEqual([]);
  });
});

describe("PLANT: timeline", () => {
  const scenes = [
    { path: "chapters/01-arrival/01-the-gate.md", header: headerOf("chapters/01-a/01-b.md", scene({ ...FULL, date: "2024-04-12" })) },
    { path: "chapters/01-arrival/02-supper.md", header: headerOf("chapters/01-a/01-b.md", scene({ ...FULL, date: "2024-04-12 19:00" })) },
    { path: "chapters/02-letters/01-morning.md", header: headerOf("chapters/01-a/01-b.md", scene({ ...FULL, date: "2024-04-13" })) },
  ].map((s) => ({ ...s, header: { ...s.header } }));
  const path = "chapters/02-letters/02-the-letter.md";

  it("flags a scene dated before the one it follows, with no flashback mark", () => {
    const source = scene({ ...FULL, date: "2024-04-12 08:00" });
    const found = checkTimeline(path, source, headerOf(path, source), scenes);
    expect(found).toHaveLength(1);
    expect(found[0]!.message).toBe(
      "Dated 2024-04-12 08:00, before the scene it follows (chapters/02-letters/01-morning.md, 2024-04-13), and not marked flashback: true.",
    );
  });

  it("CLEAN TWIN: the same scene marked flashback: true is not flagged", () => {
    const source = scene({ ...FULL, date: "2024-04-12 08:00", flashback: true });
    expect(checkTimeline(path, source, headerOf(path, source), scenes)).toEqual([]);
  });

  it("CLEAN TWIN: a scene in order is not flagged, and a flashback before it does not move the clock", () => {
    const withFlashback = [...scenes, { path: "chapters/02-letters/02-summer-1990.md", header: { ...scenes[0]!.header, date: "1990-07-01", flashback: true } }];
    const next = "chapters/02-letters/03-noon.md";
    const source = scene({ ...FULL, date: "2024-04-13 12:00" });
    expect(checkTimeline(next, source, headerOf(next, source), withFlashback)).toEqual([]);
  });

  it("orders chapter 100 after chapter 99", () => {
    const late = [{ path: "chapters/99-late/01-a.md", header: { ...scenes[0]!.header, date: "2030-01-01" } }];
    const p = "chapters/100-later/01-b.md";
    const source = scene({ ...FULL, date: "2029-01-01" });
    expect(checkTimeline(p, source, headerOf(p, source), late)).toHaveLength(1);
  });

  it("reads story dates strictly", () => {
    expect(storyDate("2024-04-12")).toBe("2024-04-12T00:00");
    expect(storyDate("2024-04-12 19:05")).toBe("2024-04-12T19:05");
    expect(storyDate("April 12")).toBeNull();
    expect(storyDate("2024-13-01")).toBeNull();
  });
});

describe("PLANT: world rules", () => {
  const path = "chapters/01-arrival/01-the-gate.md";

  it("flags a forbidden pattern from a rule, on the file's own line", () => {
    const source = scene(FULL, "The road was quiet.\n\nThen the phone rang in his pocket.\n");
    const found = checkWorldRules(path, source, BIBLE.rules);
    expect(found).toHaveLength(1);
    expect(found[0]).toMatchObject({ check: "world-rules", line: 13, excerpt: "phone rang" });
    expect(found[0]!.message).toBe('Breaks the rule "No phones past the ridge" (forbidden: \\bphone rang\\b).');
  });

  it("CLEAN TWIN: prose that keeps the rule is not flagged", () => {
    expect(checkWorldRules(path, scene(FULL, "He had no signal, and the phone stayed dark.\n"), BIBLE.rules)).toEqual([]);
  });

  it("flags a rule whose pattern cannot compile, on the rule's own file", () => {
    const found = checkRuleFile("bible/rules/phones.md", "---\nname: Phones\nforbidden: [\"(unclosed\"]\n---\n", { name: "Phones", forbidden: ["(unclosed"] });
    expect(found).toHaveLength(1);
    expect(found[0]).toMatchObject({ path: "bible/rules/phones.md", line: 3, excerpt: "(unclosed" });
  });
});

describe("PLANT: AI habits", () => {
  const path = "chapters/01-arrival/01-the-gate.md";
  const habits = readHabits(null);
  const run = (body: string) => checkAiHabits(path, scene(FULL, body), habits);

  it("flags the \"it's not just X, it's Y\" construction, in both its forms", () => {
    expect(run("It's not just a house, it's a promise.\n")).toMatchObject([{ message: `The "not X, it's Y" construction.` }]);
    expect(run("This wasn't about money. It was about pride.\n")).toMatchObject([{ message: `The "not X, it's Y" construction.` }]);
    expect(run("It isn't only about the land; it's about the name.\n")).toHaveLength(1);
  });

  it("flags a banned word, as a whole word and in any case", () => {
    const found = run("The Tapestry of the hills.\n");
    expect(found).toMatchObject([{ message: '"tapestry" is on the AI-habits list.', excerpt: "Tapestry" }]);
    expect(run("Tapestries hung in the hall.\n")).toEqual([]);
  });

  it("flags a paragraph that closes on a rule-of-three list", () => {
    const found = run("She stood on the porch a long time.\nIt was bold, brave, and beautiful.\n");
    expect(found).toMatchObject([{ message: "The paragraph closes on a rule-of-three list.", line: 12, excerpt: "It was bold, brave, and beautiful." }]);
  });

  it("CLEAN TWIN: the same ideas without the habits are not flagged", () => {
    expect(run("It's not raining, so we walked.\n\nIt was a house. He meant it as a promise.\n")).toEqual([]);
    expect(run("She bought eggs, flour, and a sack of rice for the week.\n\nThey talked about it, and then they went to bed.\n")).toEqual([]);
    // A triad inside a paragraph, not closing it, is ordinary prose.
    expect(run("He packed shirts, socks, and boots. Then he drove north.\n")).toEqual([]);
  });

  it("takes words from shared/checks/ai-habits.md and lets Dustin allow one back", () => {
    const custom = readHabits("---\nwords: [suddenly]\nallow: [journey, discover]\n---\n");
    expect(custom.words).toContain("suddenly");
    expect(custom.words).not.toContain("journey");
    expect(checkAiHabits(path, scene(FULL, "Suddenly the journey was over.\n"), custom).map((f) => f.excerpt)).toEqual(["Suddenly"]);
    expect(readHabits("---\nconditions: false\n---\n").conditions).toBe(false);
  });

  it("reads the novels repository's shared/checks/ai-habits.md as it ships: the seed, unchanged", () => {
    const shipped = [
      "---",
      "# Added to the AI-habits list Carrel starts from (the AI-tells list in the portfolio conventions).",
      "words: []",
      "# Words from that list to allow back. In fiction some of them are ordinary words; a flag is only a flag.",
      "allow: []",
      "# Set to false to stop flagging the constructions (\"it's not just X, it's Y\", a paragraph closing on",
      "# a rule-of-three list) and keep only the words.",
      "conditions: true",
      "---",
      "",
      "Carrel reads the header above. Anything written here, below it, is for people.",
      "",
    ].join("\r\n");
    expect(readHabits(shipped)).toEqual({ words: SEED_WORDS, conditions: true });
  });

  it("seeds from the AI-tells list in capsid/conventions.md", () => {
    expect(SEED_WORDS).toEqual(expect.arrayContaining(["delve", "tapestry", "testament to", "it's worth noting", "furthermore"]));
  });
});

describe("PLANT: voice", () => {
  const profile = profileOf(BASELINE);
  const path = "chapters/01-arrival/01-the-gate.md";

  it("has a profile to compare with", () => {
    expect(profile).not.toBeNull();
    expect(profile!.chunks).toBeGreaterThanOrEqual(3);
  });

  it("flags a public-domain passage by another author among Dustin's", () => {
    const found = checkVoice(path, scene(FULL, PLANT), profile);
    expect(found).toHaveLength(1);
    expect(found[0]!.check).toBe("voice");
    expect(found[0]!.message).toMatch(/^Reads unlike your passages in shared\/voice\/ \(distance \d\.\d\d, flagged from 1\.1\): sentences average/);
  });

  it("CLEAN TWIN: more of Dustin's register, not in the passages, is not flagged", () => {
    expect(checkVoice(path, scene(FULL, TWIN), profile)).toEqual([]);
  });

  it("stays silent without passages to compare with, or on a short scene", () => {
    expect(checkVoice(path, scene(FULL, PLANT), null)).toEqual([]);
    expect(profileOf([BASELINE[0]!.slice(0, 400)])).toBeNull();
    expect(checkVoice(path, scene(FULL, PLANT.slice(0, 600)), profile)).toEqual([]);
  });
});

describe("the header and checkFile", () => {
  const context: BookContext = { bible: BIBLE, scenes: [], habits: readHabits(null), voice: null };

  it("PLANT: a scene with no header is flagged, and so is a missing field", () => {
    expect(checkFile("chapters/01-a/01-b.md", "Just prose.\n", context).map((f) => f.check)).toContain("header");
    const found = checkFile("chapters/01-a/01-b.md", scene({ ...FULL, location: "", outcome: "" }), context);
    expect(found.map((f) => f.message)).toEqual(["The header has no location.", "The beats have no outcome yet."]);
  });

  it("CLEAN TWIN: a complete, clean scene has no findings", () => {
    expect(checkFile("chapters/01-a/01-b.md", scene(FULL, "Wade opened the gate.\n"), context)).toEqual([]);
  });

  it("does not check a bible entry or an outline as prose", () => {
    expect(checkFile("bible/characters/wade.md", "---\nname: Wade\n---\nIt's not just a man, it's a tapestry.\n", context)).toEqual([]);
    expect(checkFile("outline/plan.md", "It was bold, brave, and beautiful.\n", context)).toEqual([]);
  });

  it("gives repeats of the same finding their own fingerprints", async () => {
    const found = checkAiHabits("x", scene(FULL, "A tapestry.\n\nAnother tapestry.\n"), readHabits(null));
    expect(found).toHaveLength(2);
    const keys = await fingerprints(found.map((f) => ({ ...f, line: null })));
    expect(new Set(keys).size).toBe(2);
  });
});

test/books.test.ts.source:
// Books through Carrel's service layer, against the fake novels repository: who may open, save and
// export; a save that commits with the version it expects and records who wrote what; the checks
// that run on save and never stop it; and export held while a flag is open.

import { beforeEach, describe, expect, it } from "vitest";

import {
  assembleBook,
  authorshipRecord,
  authorshipReport,
  checkDraft,
  createBook,
  dismissFinding,
  exportGate,
  listFiles,
  listFindings,
  refreshBook,
  requireBookProject,
  saveBookFile,
  wordDelta,
} from "~/lib/books.server";
import { autosave, readDraft } from "~/lib/content.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addBook, addPerson, addProject, resetDb, share, testEnv } from "./env";
import { BASELINE, PLANT } from "./fixtures/voice";
import { fakeNovels } from "./novels";
import { viewerFor } from "./site";

const SLUG = "test-book";

const WADE = "---\nname: Wade Pruitt\naliases: [Wade]\nborn: 1996-02-11\n---\nRanch hand.\n";
const PLACE = "---\nname: Harlan place\n---\n";
const RULE = "---\nname: No phones past the ridge\nforbidden: [phone rang]\n---\n";
const HEADER = "---\npov: Wade\ndate: 2024-04-12\nlocation: Harlan place\ncharacters: [Wade]\ngoal: get in\nconflict: the lock\noutcome: he opens it\n---\n\n";

function seedRepo(extra: Record<string, string> = {}) {
  return fakeNovels({
    [`${SLUG}/book.md`]: "---\ntitle: The Test Book\nauthor: Test Author\n---\n",
    [`${SLUG}/bible/characters/wade.md`]: WADE,
    [`${SLUG}/bible/places/harlan-place.md`]: PLACE,
    [`${SLUG}/bible/rules/phones.md`]: RULE,
    [`${SLUG}/chapters/01-arrival/01-the-gate.md`]: `${HEADER}Wade opened the gate.\n`,
    [`${SLUG}/chapters/01-arrival/02-supper.md`]: HEADER.replace("2024-04-12", "2024-04-12 19:00") + "They ate at the kitchen table.\n",
    [`${SLUG}/outline/plan.md`]: "# Plan\n",
    [`${SLUG}/build/book.epub`]: "ignored",
    [`${SLUG}/notes.txt`]: "ignored",
    "shared/checks/ai-habits.md": "---\nwords: [suddenly]\n---\n",
    ...extra,
  });
}

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addBook(SLUG);
  await share(id, editor, "editor");
  await share(id, reader, "reader");
});

async function as(email: string, action: "read" | "edit" | "publish" = "read") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireBookProject(testEnv.DB, viewer, SLUG, action) };
}

describe("opening a book", () => {
  it("PLANT: a non-member, a missing book, and a site all answer 404", async () => {
    const stranger = await viewerFor("stranger@test.invalid");
    const owner = await viewerFor("owner@test.invalid");
    await addProject("a-site", "dustinedwards");
    expect(await refusal(requireBookProject(testEnv.DB, stranger, SLUG, "read"))).toBe(404);
    expect(await refusal(requireBookProject(testEnv.DB, owner, "no-such-book", "read"))).toBe(404);
    expect(await refusal(requireBookProject(testEnv.DB, owner, "a-site", "read"))).toBe(404);
    // And the other way: a book is not a site.
    expect(await refusal(requireSiteProject(testEnv.DB, owner, SLUG, "read"))).toBe(404);
  });

  it("PLANT: a Reader asking to edit is refused 403", async () => {
    const reader = await viewerFor("reader@test.invalid");
    expect(await refusal(requireBookProject(testEnv.DB, reader, SLUG, "edit"))).toBe(403);
  });

  it("creates a book for the Owner only, with a folder name the layout allows", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const editor = await viewerFor("editor@test.invalid");
    expect(await refusal(createBook(testEnv.DB, editor, { name: "Mine", folder: "mine" }))).toBe(403);
    expect(await createBook(testEnv.DB, owner, { name: "Paluxy Portal", folder: "paluxy-portal" })).toEqual({ ok: true, slug: "paluxy-portal" });
    expect((await createBook(testEnv.DB, owner, { name: "Again", folder: "paluxy-portal" })).ok).toBe(false);
    expect((await createBook(testEnv.DB, owner, { name: "Bad", folder: "../etc" })).ok).toBe(false);
    expect((await createBook(testEnv.DB, owner, { name: "Shared", folder: "shared" })).ok).toBe(false);
  });
});

describe("refresh from Git", () => {
  it("indexes the book's Markdown files by kind, skips build/ and other files, and reads shared/", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    const result = await refreshBook(testEnv.DB, gh.repo, project);
    expect(result).toMatchObject({ files: 7, read: 7, removed: 0, shared: 1, more: false });
    const files = await listFiles(testEnv.DB, project);
    expect(files.map((f) => [f.path, f.kind])).toEqual([
      ["bible/characters/wade.md", "character"],
      ["bible/places/harlan-place.md", "place"],
      ["bible/rules/phones.md", "rule"],
      ["book.md", "book"],
      ["chapters/01-arrival/01-the-gate.md", "scene"],
      ["chapters/01-arrival/02-supper.md", "scene"],
      ["outline/plan.md", "outline"],
    ]);
    // A clean book has nothing flagged.
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
  });

  it("reads again only what changed, and drops what Git no longer has", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    gh.files.delete(`${SLUG}/outline/plan.md`);
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-supper.md`, `${HEADER}Suddenly they ate.\n`);
    const before = gh.requests.length;
    expect(await refreshBook(testEnv.DB, gh.repo, project)).toMatchObject({ read: 1, removed: 1, shared: 0 });
    expect(gh.requests.slice(before).filter((r) => r.includes("/contents/"))).toEqual([
      `GET /repos/DrDustinEdwards/novels/contents/${SLUG}/chapters/01-arrival/02-supper.md`,
    ]);
    // The checks ran on what changed outside Carrel, with the book's own habits list.
    expect((await listFindings(testEnv.DB, project)).map((f) => f.excerpt)).toEqual(["Suddenly"]);
  });
});

describe("saving", () => {
  it("PLANT: a Reader cannot autosave or save, and Git hears nothing", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("reader@test.invalid");
    const path = "chapters/01-arrival/01-the-gate.md";
    expect(await refusal(autosave(testEnv.DB, project, viewer, path, { source: "x", baseVersion: null }))).toBe(403);
    expect(await refusal(saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "x", expectedVersion: null }))).toBe(403);
    expect(gh.requests.filter((r) => r.startsWith("PUT"))).toEqual([]);
  });

  it("PLANT: a path outside the layout is refused before Git is asked", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    for (const path of ["../other-book/book.md", "build/x.md", "chapters/one/two.md", "notes.txt", "chapters/01-a/01-b.md/../../x.md"]) {
      expect(await refusal(saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "x", expectedVersion: null }))).toBe(404);
    }
    expect(gh.requests).toEqual([]);
  });

  it("commits as the person with a change id and no AI trailer, records authorship, clears the draft", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("editor@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/01-the-gate.md";
    const file = (await listFiles(testEnv.DB, project)).find((f) => f.path === path)!;
    await autosave(testEnv.DB, project, viewer, path, { source: "draft", baseVersion: file.sha });

    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, {
      source: `${HEADER}Wade opened the old gate slowly.\n`,
      expectedVersion: file.sha,
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(gh.commits).toHaveLength(1);
    expect(gh.commits[0]).toMatchObject({ path: `${SLUG}/${path}`, author: { name: "editor", email: "editor@test.invalid" } });
    expect(gh.commits[0]!.message).toBe(`Save ${SLUG}/${path}\n\nCarrel-Change: ${result.changeId}`);
    expect(gh.commits[0]!.message).not.toMatch(/claude|anthropic|co-authored/i);
    expect(await readDraft(testEnv.DB, project, viewer, path)).toBeNull();

    const record = await authorshipRecord(testEnv.DB, project);
    expect(record).toMatchObject([{ id: result.changeId, path, who: "editor", client: null, wordsAdded: 2, wordsRemoved: 0, commit: result.commit }]);
    const report = authorshipReport(project, record, new Date("2026-09-27T00:00:00Z"));
    expect(report).toContain("| editor | 1 | 2 | 0 |");
    expect(report).toContain(`| editor | ${path} | 2 | 0 | ${result.commit.slice(0, 7)} |`);
  });

  it("PLANT: a stale expected version is refused as a conflict, and the draft is kept", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/01-the-gate.md";
    const opened = (await listFiles(testEnv.DB, project)).find((f) => f.path === path)!.sha;
    await autosave(testEnv.DB, project, viewer, path, { source: "my words", baseVersion: opened });
    await gh.commitElsewhere(`${SLUG}/${path}`, `${HEADER}Someone else's words.\n`);

    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "my words", expectedVersion: opened });
    expect(result).toMatchObject({ ok: false, reason: "conflict" });
    expect(gh.files.get(`${SLUG}/${path}`)!.source).toBe(`${HEADER}Someone else's words.\n`);
    expect((await readDraft(testEnv.DB, project, viewer, path))?.source).toBe("my words");
    expect(await authorshipRecord(testEnv.DB, project)).toEqual([]);
  });

  it("creates a new scene only where no file exists", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    const path = "chapters/02-letters/01-morning.md";
    const created = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: `${HEADER.replace("2024-04-12", "2024-04-13")}Morning.\n`, expectedVersion: null });
    expect(created.ok).toBe(true);
    const again = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "overwrite", expectedVersion: null });
    expect(again).toMatchObject({ ok: false, reason: "conflict" });
  });
});

describe("checks on save", () => {
  it("PLANT: a flagged scene still saves; the flags come back and are recorded", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/03-late.md";
    const source = HEADER.replace("characters: [Wade]", "characters: [Wade, Tobias]").replace("2024-04-12", "2024-04-11") + "Then the phone rang. It's not just a farm, it's a promise.\n";
    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source, expectedVersion: null });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(gh.files.get(`${SLUG}/${path}`)!.source).toBe(source);
    expect(result.findings.map((f) => f.check).sort()).toEqual(["ai-habits", "continuity", "timeline", "world-rules"]);
    expect((await listFindings(testEnv.DB, project, { path })).map((f) => f.check).sort()).toEqual(["ai-habits", "continuity", "timeline", "world-rules"]);
  });

  it("PLANT: the voice check flags another author's passage once shared/voice/ holds Dustin's", async () => {
    const voice = Object.fromEntries(BASELINE.map((text, i) => [`shared/voice/passage-${i + 1}.md`, text]));
    const gh = seedRepo({ ...voice, "shared/voice/README.md": "Put your passages here." });
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, "chapters/01-arrival/03-tea.md", {
      source: HEADER.replace("2024-04-12", "2024-04-13") + PLANT,
      expectedVersion: null,
    });
    expect(result.ok && result.findings.map((f) => f.check)).toEqual(["voice"]);
  });

  it("fixing the text clears the flag; saving a bible entry rechecks every scene", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/03-late.md";
    const withTobias = HEADER.replace("characters: [Wade]", "characters: [Wade, Tobias]").replace("2024-04-12", "2024-04-13") + "Quiet.\n";
    const saved = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: withTobias, expectedVersion: null });
    expect((await listFindings(testEnv.DB, project, { status: "open" })).map((f) => f.excerpt)).toEqual(["Tobias"]);

    // Adding Tobias to the bible resolves the scene's flag without touching the scene.
    const bible = await saveBookFile(testEnv.DB, gh.repo, project, viewer, "bible/characters/tobias.md", { source: "---\nname: Tobias\n---\n", expectedVersion: null });
    expect(bible.ok && saved.ok).toBe(true);
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
  });

  it("checks a draft without saving or recording anything", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const found = await checkDraft(testEnv.DB, project, "chapters/01-arrival/01-the-gate.md", `${HEADER}A tapestry.\n`);
    expect(found.map((f) => f.excerpt)).toEqual(["tapestry"]);
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
    expect(gh.requests.filter((r) => r.startsWith("PUT"))).toEqual([]);
  });
});

describe("dismissing flags and exporting", () => {
  async function flagged() {
    const gh = seedRepo();
    const owner = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, owner.project);
    await saveBookFile(testEnv.DB, gh.repo, owner.project, owner.viewer, "chapters/01-arrival/03-late.md", {
      source: HEADER.replace("2024-04-12", "2024-04-13") + "A tapestry. Another tapestry.\n",
      expectedVersion: null,
    });
    return { gh, owner };
  }

  it("PLANT: export is refused while a flag is open, and to anyone but the Owner", async () => {
    const { owner } = await flagged();
    expect(await exportGate(testEnv.DB, owner.project)).toMatchObject({ ok: false, open: 2 });
    const editor = await as("editor@test.invalid");
    expect(await refusal(exportGate(testEnv.DB, editor.project))).toBe(403);
    expect(await refusal(assembleBook(testEnv.DB, editor.project, editor.viewer))).toBe(403);
  });

  it("PLANT: an Editor cannot dismiss a flag; the Owner can, and a dismissal survives the next save", async () => {
    const { gh, owner } = await flagged();
    const editor = await as("editor@test.invalid");
    const [first, second] = await listFindings(testEnv.DB, owner.project);
    expect(await refusal(dismissFinding(testEnv.DB, editor.project, editor.viewer, first!.id))).toBe(403);

    await dismissFinding(testEnv.DB, owner.project, owner.viewer, first!.id);
    await dismissFinding(testEnv.DB, owner.project, owner.viewer, second!.id);
    expect(await exportGate(testEnv.DB, owner.project)).toEqual({ ok: true });

    // Saving again with the same words keeps both dismissed; a new tapestry is a new flag.
    const path = "chapters/01-arrival/03-late.md";
    const current = gh.files.get(`${SLUG}/${path}`)!;
    await saveBookFile(testEnv.DB, gh.repo, owner.project, owner.viewer, path, { source: `${current.source}A third tapestry.\n`, expectedVersion: current.sha });
    const all = await listFindings(testEnv.DB, owner.project);
    expect(all.map((f) => f.status).sort()).toEqual(["dismissed", "dismissed", "open"]);
  });

  it("a dismissal in another book cannot be reached by id", async () => {
    const { owner } = await flagged();
    const [finding] = await listFindings(testEnv.DB, owner.project);
    await addBook("other-book");
    const other = await requireBookProject(testEnv.DB, owner.viewer, "other-book", "publish");
    expect(await refusal(dismissFinding(testEnv.DB, other, owner.viewer, finding!.id))).toBe(404);
  });

  it("assembles the book in reading order with its title and author from book.md", async () => {
    const gh = seedRepo({ [`${SLUG}/chapters/10-late/01-end.md`]: `${HEADER.replace("2024-04-12", "2024-05-01")}The end.\n` });
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const book = await assembleBook(testEnv.DB, project, viewer);
    expect(book.title).toBe("The Test Book");
    expect(book.author).toBe("Test Author");
    expect(book.chapters.map((c) => [c.title, c.scenes.map((s) => s.body)])).toEqual([
      ["Arrival", ["Wade opened the gate.", "They ate at the kitchen table."]],
      ["Late", ["The end."]],
    ]);
  });
});

describe("word counts for the authorship record", () => {
  it("counts a changed word once each way and a moved word not at all", () => {
    expect(wordDelta("the cat sat", "the dog sat")).toEqual({ added: 1, removed: 1 });
    expect(wordDelta("a b c", "c b a")).toEqual({ added: 0, removed: 0 });
    expect(wordDelta(null, "---\ntitle: x\n---\none two")).toEqual({ added: 2, removed: 0 });
  });
});

